important = [
 IM("Define chronic inflammation and list its characteristic reactions.", "عرّف الالتهاب المزمن وعدّد تفاعلاته المميّزة.", "Inflammation of prolonged duration (weeks to years) with continuing inflammation, tissue injury and healing (often by fibrosis) proceeding simultaneously; characterized by mononuclear cell infiltration, tissue destruction, and repair (angiogenesis and fibrosis).", "التهاب طويل الأمد (أسابيع إلى سنوات) تجري فيه في آنٍ واحد عمليات الالتهاب وإصابة النسيج والالتئام (غالبًا بالتليّف)؛ ويتميّز بالارتشاح بالخلايا وحيدة النواة وتدمير النسيج والإصلاح (تكوّن الأوعية والتليّف)."),
 IM("Compare acute and chronic inflammation (Table 2–1).", "قارن بين الالتهاب الحاد والمزمن (الجدول 2–1).", "Onset: fast vs slow; infiltrate: neutrophils vs monocytes/macrophages and lymphocytes; tissue injury: mild, self-limited vs severe, progressive; signs: prominent vs less prominent.", "البدء: سريع مقابل بطيء؛ الارتشاح: العدلات مقابل الوحيدات/البلاعم واللمفاويات؛ إصابة النسيج: خفيفة محدودة مقابل شديدة متفاقمة؛ العلامات: بارزة مقابل أقل بروزًا."),
 IM("List the settings in which chronic inflammation arises.", "عدّد الحالات التي ينشأ فيها الالتهاب المزمن.", "Persistent infections (TB, syphilis, viruses, fungi); immune-mediated (hypersensitivity, autoimmune) diseases; prolonged exposure to toxic agents (silica, cholesterol crystals); mild chronic inflammation in diseases such as Alzheimer, atherosclerosis, metabolic syndrome/type 2 diabetes and cancer.", "العدوى المستمرة (السل، الزهري، الفيروسات، الفطريات)؛ الأمراض المتوسَّطة مناعيًا (فرط الحساسية، المناعة الذاتية)؛ التعرّض الطويل لعوامل سامة (السيليكا، بلورات الكوليسترول)؛ الالتهاب المزمن الخفيف في أمراض مثل ألزهايمر وتصلّب الشرايين والمتلازمة الاستقلابية/سكري النوع الثاني والسرطان."),
 IM("Define granulomatous inflammation and list the settings of granuloma formation.", "عرّف الالتهاب الحبيبومي وعدّد حالات تكوّن الأورام الحبيبية.", "A distinctive pattern of chronic inflammation with aggregates of activated macrophages and scattered lymphocytes. Settings: persistent T-cell responses to microbes (TB prototype, T. pallidum, fungi); immune-mediated diseases (Crohn disease); sarcoidosis and foreign body granulomas.", "نمط مميّز من الالتهاب المزمن فيه تجمّعات من البلاعم المنشَّطة ولمفاويات متناثرة. حالاته: استجابات تائية مستمرة للميكروبات (السل نموذجها، الزهري، الفطريات)؛ الأمراض المتوسَّطة مناعيًا (داء كرون)؛ الساركويد والأورام الحبيبية للأجسام الغريبة."),
 IM("What is the acute-phase reaction and its main mediators?", "ما تفاعل الطور الحاد وما وسائطه الرئيسة؟", "The systemic effects of inflammation (systemic inflammatory response syndrome); main mediators TNF, IL-1 and IL-6; IL-6 stimulates hepatic synthesis of plasma proteins.", "التأثيرات الجهازية للالتهاب (متلازمة الاستجابة الالتهابية الجهازية)؛ وسائطه الرئيسة TNF وIL-1 وIL-6؛ ويحفّز IL-6 الكبد على تخليق بروتينات البلازما."),
 IM("Explain how fever is produced.", "اشرح كيف تُحدث الحمّى.", "Pyrogens (e.g., LPS, pyrogenic cytokines IL-1, TNF, IL-6) stimulate prostaglandin (PGE₂) synthesis in vascular and perivascular cells of the hypothalamus, raising the set-point.", "تحفّز المولّدات الحرارية (مثل LPS والسيتوكينات IL-1 وTNF وIL-6) تخليق البروستاغلاندين (PGE₂) في الخلايا الوعائية وحول الوعائية للوطاء فترتفع نقطة الضبط."),
 IM("Name the three best known acute-phase proteins and their roles.", "سمِّ بروتينات الطور الحاد الثلاثة الأشهر وأدوارها.", "CRP and SAA bind microbial walls, act as opsonins and fix complement; fibrinogen causes rouleaux, the basis of the ESR. Synthesized in the liver, stimulated mainly by IL-6.", "CRP وSAA يرتبطان بجدران الميكروبات ويعملان طاهيات ويثبّتان المتمّمة؛ والفيبرينوجين يسبّب الرصّ وهو أساس ESR. تُخلَّق في الكبد بتحفيز IL-6 أساسًا."),
 IM("Give examples of leukocyte changes in different infections.", "أعطِ أمثلة على تغيّرات الكريات البيض في أنواع العدوى المختلفة.", "Bacterial → neutrophilia; viral (infectious mononucleosis, mumps, German measles) → lymphocytosis; asthma, hay fever, parasites → eosinophilia; typhoid, some viruses, rickettsiae, protozoa → leukopenia.", "البكتيرية ← كثرة العدلات؛ الفيروسية (كثرة الوحيدات العدوائي، النكاف، الحصبة الألمانية) ← كثرة اللمفاويات؛ الربو وحمّى القش والطفيليات ← كثرة الحمضات؛ التيفوئيد وبعض الفيروسات والريكتسيات والأوالي ← قلّة الكريات البيض."),
]
